secureScript.script:
import com.cloudbees.plugins.credentials.CredentialsProvider
import com.cloudbees.plugins.credentials.common.StandardUsernamePasswordCredentials
import jenkins.model.Jenkins

if (APPLICATION == null || APPLICATION.toString().trim() == '') {
    return "<textarea name='value' rows='5'>Select an application above first.</textarea>"
}

def creds = CredentialsProvider.lookupCredentials(
    StandardUsernamePasswordCredentials.class, Jenkins.instance, null, null
).find { it.id == 'github-credentials' }

def url = "https://raw.githubusercontent.com/mohitjangale8/pinakaone-gitops/main/charts/${APPLICATION}/values.yaml"
def conn = new URL(url).openConnection()
if (creds != null) {
    conn.setRequestProperty("Authorization", "token " + creds.password.plainText)
}
def fullYaml = conn.getInputStream().getText()

def tmp = File.createTempFile('values', '.yaml')
tmp.text = fullYaml
def proc = ['/usr/local/bin/yq', 'e', '.config', tmp.absolutePath].execute()
proc.waitFor()
def content = proc.exitValue() == 0 ? proc.text : "# error extracting config (exit ${proc.exitValue()})"
tmp.delete()

def esc = content.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
return "<textarea name='value' rows='20' style='width:100%;font-family:monospace;font-size:13px;'>${esc}</textarea>"
